/**
 * Generate the procedural fixture skin the offline suites run against.
 *
 * The public repository ships no artwork, so the suites get one tiny skin that
 * is *computed*: a synthetic 64×64 background goes through the same measurement
 * and derivation code the product uses (`analyzeSample` → `buildRecord` →
 * `deriveDesign` → `buildTokens` → `themeCss`), then the generator writes a
 * complete skin directory. Nothing is copied from any real wallpaper.
 *
 * Usage: run from the sandbox root (tests/run.mjs does that):
 *   node tests/fixtures/make-fixture-skin.mjs
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { deflateSync } from 'node:zlib';
import { pathToFileURL } from 'node:url';

const root = process.cwd();
const plugin = join(root, 'output', 'plugin', 'dsh-skins');
const skinId = 'img_fixture_00000000';

/* ── the product's own measurement code, sliced from the shipped source ───── */
const body = readFileSync(join(plugin, 'src', 'client.body.js'), 'utf8');
const start = body.indexOf('function rgbToHsl(');
const end = body.indexOf('/** Decode an image file and sample it down');
if (start === -1 || end === -1) throw new Error('could not slice the measurement helpers out of client.body.js');
const api = new Function(`${body.slice(start, end)}; return { analyzeSample, pickPalette, buildRecord, hslToHex, rgbToHsl };`)();

/* ── the product's own derivation + emission ──────────────────────────────── */
const { deriveDesign, buildTokens, themeCss } = await import(
  pathToFileURL(join(root, 'output', '_scan', 'skin_derive.mjs')).href
);

/** A synthetic background: a warm dark field, a saturated blob, and grain. */
function pixels(size = 64) {
  const data = new Uint8ClampedArray(size * size * 4);
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const at = (y * size + x) * 4;
      const inBlob = Math.abs(x - size * 0.35) < size * 0.18 && Math.abs(y - size * 0.4) < size * 0.22;
      const source = inBlob ? [193, 118, 74] : [38, 41, 52];
      const noise = ((x * 37 + y * 17) % 7) - 3;
      data[at] = source[0] + noise;
      data[at + 1] = source[1] + noise;
      data[at + 2] = source[2] + noise;
      data[at + 3] = 255;
    }
  }
  return data;
}

const stats = api.analyzeSample(pixels(), 64, 64);
const scan = {
  skinId,
  slug: 'fixture',
  kind: 'image',
  relPath: 'fixtures/source.png',
  bytes: 1024,
  width: 64,
  height: 64,
  durationSeconds: null,
  bitrateMbps: null,
};
const record = api.buildRecord({ native: { width: 64, height: 64 }, stats }, scan);
const spec = deriveDesign(record, scan);
const meta = {
  skinId,
  slug: scan.slug,
  name: 'Procedural Fixture',
  nameZh: '程序化样例',
  kind: 'image',
  source: scan.relPath,
  sourceBytes: scan.bytes,
  sourceSize: { width: scan.width, height: scan.height },
  durationSeconds: null,
  bitrateMbps: null,
  analysisRecord: 'tests/fixtures/make-fixture-skin.mjs (synthetic)',
  artwork: {
    primaryColor: record.primaryColor,
    secondaryColors: record.secondaryColors,
    accentColor: record.accentColor,
    neutrals: record.neutrals,
    temperature: record.temperature,
    saturation: record.saturation,
    luminance: record.luminance,
    contrast: record.contrast,
  },
  material: record.material,
  lighting: record.lighting,
  busyness: record.busyness,
  styleKeywords: record.styleKeywords ?? [],
  mood: record.mood ?? [],
  posterProvenance: '',
  frameCount: null,
  sampledTimes: null,
  frameDrift: null,
  motionNote: null,
  posterAdvice: null,
};
const tokens = buildTokens(spec, meta);
const css = themeCss(spec, meta);

/* ── write the skin ───────────────────────────────────────────────────────── */
const dir = join(root, 'output', 'skins', skinId);
mkdirSync(join(dir, 'assets'), { recursive: true });
writeFileSync(
  join(dir, 'skin.json'),
  `${JSON.stringify({
    skinId,
    name: meta.name,
    nameZh: meta.nameZh,
    type: 'image',
    source: { file: 'fixtures/source.png' },
    assets: { wallpaper: 'assets/wallpaper.webp', thumb: 'assets/thumb.webp' },
    generatedBy: 'tests/fixtures/make-fixture-skin.mjs',
    note: 'procedural fixture — not artwork',
  }, null, 2)}\n`,
);
writeFileSync(join(dir, 'tokens.json'), `${JSON.stringify({ presentedTokens: tokens.presentedTokens, contrast: tokens.contrast }, null, 2)}\n`);
writeFileSync(join(dir, 'theme.css'), css);
writeFileSync(join(dir, 'README.md'), '# Procedural Fixture\n\nGenerated by `tests/fixtures/make-fixture-skin.mjs`. No third-party artwork.\n');
writeFileSync(join(dir, 'preview.html'), `<!doctype html><meta charset="utf-8"><title>Procedural Fixture</title><body style="margin:0;font:14px system-ui;background:#1a1d24;color:#e7e9ee">Fixture skin — generated, not artwork.</body>\n`);
writeFileSync(join(dir, 'assets', 'wallpaper.webp'), png(64, 64, [38, 41, 52]));
writeFileSync(join(dir, 'assets', 'thumb.webp'), png(32, 18, [60, 64, 78]));

console.log(`fixture skin: ${skinId} tokens=${Object.keys(tokens.presentedTokens).length} anchor=${spec.anchorScheme}`);

/* ── a minimal PNG encoder (no dependencies, deterministic) ───────────────── */
function png(width, height, [r, g, b]) {
  const raw = Buffer.alloc((width * 3 + 1) * height);
  for (let y = 0; y < height; y += 1) {
    const row = y * (width * 3 + 1);
    raw[row] = 0;
    for (let x = 0; x < width; x += 1) {
      const at = row + 1 + x * 3;
      raw[at] = r;
      raw[at + 1] = g;
      raw[at + 2] = b;
    }
  }
  const chunk = (type, data) => {
    const length = Buffer.alloc(4);
    length.writeUInt32BE(data.length);
    const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(body));
    return Buffer.concat([length, body, crc]);
  };
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width, 0);
  header.writeUInt32BE(height, 4);
  header[8] = 8;
  header[9] = 2;
  header[10] = 0;
  header[11] = 0;
  header[12] = 0;
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', header),
    chunk('IDAT', deflateSync(raw)),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

function crc32(buffer) {
  let c = 0xffffffff;
  for (const byte of buffer) {
    c ^= byte;
    for (let bit = 0; bit < 8; bit += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  }
  return (c ^ 0xffffffff) >>> 0;
}
